      .retry(2)
      .end((error, res) => {
        try {
          assert.ifError(error);
          assert(res.ok, 'response should be ok');
          assert.equal(res.text, `ok = ${url}&string=ified&json=ed`);
          done();
        } catch (err) {
          done(err);
        }
      });
